const SCENE_MAP={1:'balcony',2:'seminary',3:'river',4:'tokiwadai',5:'church',6:'balcony',7:'balcony',8:'balcony',9:'balcony',10:'front',11:'inferno',12:'wing',13:'balcony',14:'balcony',15:'balcony',16:'balcony',17:'balcony',18:'balcony',19:'balcony',20:'balcony',21:'balcony',22:'balcony',23:'balcony',24:'balcony',25:'balcony',26:'balcony',27:'balcony',28:'tokiwadai',29:'balcony',30:'balcony'};/* v0.60：原先 13-30 关全部共用 dark/默认板，现逐关指向文件里已存在的复刻板 */
const QUEST_FRAME={1:'half',2:'half',3:'half',4:'half',5:'half',6:'full',7:'half',8:'half',9:'half',10:'half',11:'half',12:'full'};
