_q('#spoilerToggle').onclick=e=>{const on=e.currentTarget.getAttribute('aria-pressed')!=='true';e.currentTarget.setAttribute('aria-pressed',String(on));state.spoiler=on;save();e.currentTarget.textContent=on?'👓 剧透：开':'👓 剧透：关';if(!$('#codex').hidden)showEntry($('#entryDetail').dataset.id);announce('剧透显示'+(on?'开启':'关闭，完全剧透词条将遮罩'))};
