let voicePack={},_packI=0;
const PACK_ALIAS={'index':'茵蒂克丝','touma':'上条当麻','misaka':'御坂美琴','guide':'导览员 · 禁书目录',
 'base':'哈士喵','huskymeow':'哈士喵','accelerator':'一方通行','librarian':'结业馆长'};
function packOwner(fn){
 const s=String(fn).toLowerCase();
 const keys=[...Object.keys(PACK_ALIAS),'茵蒂克丝','上条当麻','御坂美琴','一方通行',
'导览员','哈士喵','结业馆长','神裂','史提尔','食蜂','白井','欧提努斯','爱丽丝'];
 let hit='';
 for(const k of keys){if(!k)continue;if(s.includes(String(k).toLowerCase())){hit=PACK_ALIAS[k]||k;break}}
 if(hit==='导览员')hit='导览员 · 禁书目录';
 if(hit==='神裂')hit='神裂火织';
 if(hit==='史提尔')hit='史提尔';
 return hit||'导览员 · 禁书目录';
}
function voiceAct(name,text){
 const list=voicePack[name]||voicePack['导览员 · 禁书目录'];
 if(list&&list.length){
try{speechSynthesis.cancel();speakQueue=[];speakBusy=false}catch(e){}
const a=({play:function(){},pause:function(){},load:function(){},addEventListener:function(){},removeEventListener:function(){},set volume(v){},get volume(){return 0},set currentTime(v){},get currentTime(){return 0},set src(v){},get src(){return""},set loop(v){},get loop(){return false},set muted(v){},get muted(){return true},set playbackRate(v){},get playbackRate(){return 1}});a.volume=.92;a.play().catch(()=>{});return;
 }
 if(speakOn)speak(name+'。'+text,false,name);
}
