let actorTF={},actorDrag=null,actorPointers=new Map(),actorPinch=null;
function actorKey(el){const list=[...document.querySelectorAll('#vnStage .vn-actor')];return 'a'+Math.max(0,list.indexOf(el))}
function applyActorTF(){
 document.querySelectorAll('#vnStage .vn-actor').forEach(el=>{
const k=actorKey(el),t=actorTF[k]||{x:0,y:0,s:1};
el.style.transform='translate('+t.x+'px,'+t.y+'px) scale('+t.s+')';
el.dataset.aid=k;
 });
}
function localDelta(sx,sy){
 const flip=document.body.classList.contains('ls-flip');
 if(!document.body.classList.contains('ls-mode'))return {x:sx,y:sy};
 return flip?{x:-sy,y:sx}:{x:sy,y:-sx};
}
function pokeActor(el){
 el.classList.remove('poke');void el.offsetWidth;el.classList.add('poke');
 setTimeout(()=>el.classList.remove('poke'),620);
 try{AE._noop('select')}catch(e){}
 const st=$('#vnStage');if(!st)return;
 const pop=document.createElement('span');pop.className='vn-poke-pop';
 pop.textContent=['！','♡','啊呜','✦'][Math.floor(Math.random()*4)];
 const r=el.getBoundingClientRect(),s=st.getBoundingClientRect();
 pop.style.left=Math.round(r.left-s.left+r.width*.55)+'px';
 pop.style.top=Math.round(r.top-s.top+r.height*.18)+'px';
 st.appendChild(pop);setTimeout(()=>pop.remove(),760);
}
document.addEventListener('pointerdown',e=>{
 const el=e.target.closest&&e.target.closest('#vnStage .vn-actor');if(!el)return;
 actorPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(actorPointers.size===1){
const k=actorKey(el),t=actorTF[k]||{x:0,y:0,s:1};
actorDrag={el,k,sx:e.clientX,sy:e.clientY,x0:t.x,y0:t.y,moved:0};
el.classList.add('dragging');
 }else if(actorPointers.size===2){
const p=[...actorPointers.values()];
actorPinch={d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),s:(actorTF[actorDrag?actorDrag.k:'a0']||{s:1}).s};
if(actorDrag){actorDrag.el.classList.remove('dragging');actorDrag.moved=99}
 }
},{passive:true});
document.addEventListener('pointermove',e=>{
 if(!actorDrag&&!actorPinch)return;
 if(actorPointers.has(e.pointerId))actorPointers.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(actorPinch&&actorPointers.size>=2){
const p=[...actorPointers.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y);
const k=actorDrag?actorDrag.k:'a0',t=actorTF[k]||{x:0,y:0,s:1};
t.s=Math.max(.6,Math.min(2.4,actorPinch.s*(d/Math.max(1,actorPinch.d))));actorTF[k]=t;applyActorTF();return;
 }
 if(!actorDrag)return;
 const dx=e.clientX-actorDrag.sx,dy=e.clientY-actorDrag.sy;
 actorDrag.moved=Math.max(actorDrag.moved,Math.hypot(dx,dy));
 if(actorDrag.moved<6)return;
 const d=localDelta(dx,dy),t=actorTF[actorDrag.k]||{x:0,y:0,s:1};
 t.x=actorDrag.x0+d.x;t.y=actorDrag.y0+d.y;actorTF[actorDrag.k]=t;applyActorTF();
},{passive:true});
function endActorPointer(e){
 actorPointers.delete(e.pointerId);
 if(actorPointers.size<2)actorPinch=null;
 if(actorDrag){

const dx=(e.clientX||actorDrag.sx)-actorDrag.sx,dy=(e.clientY||actorDrag.sy)-actorDrag.sy;
const mv=Math.hypot(dx,dy);
actorDrag.el.classList.remove('dragging');

if(mv<6&&actorPinch===null)pokeActor(actorDrag.el);
actorDrag=null;
 }
}
document.addEventListener('pointerup',endActorPointer,{passive:true});
document.addEventListener('pointercancel',endActorPointer,{passive:true});
document.addEventListener('click',e=>{
 if(e.target.closest&&e.target.closest('#vnStage .vn-actor'))e.stopPropagation();
},true);
document.addEventListener('dblclick',e=>{
 const el=e.target.closest&&e.target.closest('#vnStage .vn-actor');if(!el)return;
 delete actorTF[actorKey(el)];applyActorTF();toast('这只猫的位置已复位');
},{passive:true});
document.addEventListener('wheel',e=>{
 const el=e.target.closest&&e.target.closest('#vnStage .vn-actor');if(!el)return;
 e.preventDefault();
 const k=actorKey(el),t=actorTF[k]||{x:0,y:0,s:1};
 t.s=Math.max(.6,Math.min(2.4,t.s*(1-e.deltaY*.0012)));actorTF[k]=t;applyActorTF();
},{passive:false});

