function assetData(kind,id){
 if(kind==='char'){
const a=ASSET_CHARS.find(x=>x[0]===id);if(!a)return null;
return {src:ART.chars[id]||ART.chars.base,name:a[1],sub:a[2]+' · '+a[3],at:a[4],cls:'charm'};
 }
 const a=ASSET_SCENES.find(x=>x[0]===id);if(!a)return null;
 return {src:ART.scenes[id+'_h']||ART.scenes.balcony_h,name:a[1],sub:a[2],at:a[3],cls:'scene'};
}
function renderAssetCase(pfx){
 const grid=$('#'+pfx+'Grid');if(!grid)return;
 const kind=(assetPick[pfx]&&assetPick[pfx].kind)||'char';
 const list=kind==='char'?ASSET_CHARS:ASSET_SCENES;
 grid.innerHTML=list.map(a=>{
const d=assetData(kind,a[0]);if(!d)return '';
const ok=assetUnlocked(d.at);
return '<button type="button" class="asset-thumb '+d.cls+(ok?'':' locked')+'" '
+'data-kind="'+kind+'" data-id="'+a[0]+'" aria-pressed="false" aria-label="'+esc(d.name)+'">'
+'<img src="'+d.src+'" alt="'+esc(d.name)+'" loading="lazy">'
+'<span class="asset-th-name">'+esc(d.name)+'<small>'+esc(d.sub)+'</small></span>'
+(ok?'':'<span class="asset-lock">🔒 第 '+d.at+' 关解锁</span>')+'</button>';
 }).join('');
 const first=grid.querySelector('.asset-thumb');if(first)pickAsset(pfx,first);
}
function pickAsset(pfx,btn){
 const grid=$('#'+pfx+'Grid');if(!grid||!btn)return;
 grid.querySelectorAll('.asset-thumb').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));
 const kind=btn.dataset.kind,id=btn.dataset.id,d=assetData(kind,id);if(!d)return;
 if(!assetUnlocked(d.at)){toast('通关第 '+d.at+' 关后解锁这张素材');return}
 assetPick[pfx]={kind,id};
 const img=$('#'+pfx+'Img'),stage=$('#'+pfx+'Stage'),cap=$('#'+pfx+'Cap');
 if(img)img.src=d.src;
 if(stage)stage.className='asset-stage '+d.cls;
 if(cap)cap.innerHTML='<b>'+esc(d.name)+'</b><small>'+esc(d.sub)+'</small>';
 assetZoom[pfx]={x:0,y:0,s:1};applyAssetZoom(pfx);
}
function applyAssetZoom(pfx){
 const img=$('#'+pfx+'Img');if(!img)return;
 const z=assetZoom[pfx]||{x:0,y:0,s:1};
 img.style.transform='translate('+z.x+'px,'+z.y+'px) scale('+z.s+')';
}
function bindAssetCase(pfx){
 const grid=$('#'+pfx+'Grid'),tabs=$('#'+pfx+'Tabs');
 if(tabs)tabs.addEventListener('click',e=>{
const b=e.target.closest('button[data-kind]');if(!b)return;
tabs.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));
assetPick[pfx]={kind:b.dataset.kind};renderAssetCase(pfx);
 });
 if(grid)grid.addEventListener('click',e=>{const b=e.target.closest('.asset-thumb');if(b)pickAsset(pfx,b)});
 const ops=document.querySelector('#'+pfx+'Case .asset-ops');
 if(ops)ops.addEventListener('click',e=>{
const b=e.target.closest('button[data-z]');if(!b)return;
const z=assetZoom[pfx]||{x:0,y:0,s:1},stage=$('#'+pfx+'Stage');
if(b.dataset.z==='in')z.s=Math.min(4,z.s*1.2);
else if(b.dataset.z==='out')z.s=Math.max(.5,z.s/1.2);
else if(b.dataset.z==='reset'){z.x=0;z.y=0;z.s=1}
else if(b.dataset.z==='full'&&stage){stage.classList.toggle('full');return}
assetZoom[pfx]=z;applyAssetZoom(pfx);
 });
 const st=$('#'+pfx+'Stage');if(!st)return;
 let drag=null,pinch=null;
 st.addEventListener('wheel',e=>{e.preventDefault();const z=assetZoom[pfx]||{x:0,y:0,s:1};
z.s=Math.max(.5,Math.min(4,z.s*(1-e.deltaY*.0012)));assetZoom[pfx]=z;applyAssetZoom(pfx)},{passive:false});
 st.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,z:{...(assetZoom[pfx]||{x:0,y:0,s:1})}};
try{st.setPointerCapture(e.pointerId)}catch(err){}},{passive:true});
 st.addEventListener('pointermove',e=>{if(!drag)return;const z=assetZoom[pfx]||{x:0,y:0,s:1};
z.x=drag.z.x+(e.clientX-drag.x);z.y=drag.z.y+(e.clientY-drag.y);assetZoom[pfx]=z;applyAssetZoom(pfx)},{passive:true});
 st.addEventListener('pointerup',()=>{drag=null},{passive:true});
 st.addEventListener('pointercancel',()=>{drag=null},{passive:true});
}

