let tf18={},drag18=null,pts18=new Map(),pinch18=null;
function actors18(){return [...document.querySelectorAll('#vnStage .vn-actor')]}
function normalizeActors(){
 const st=$('#vnStage');if(!st)return;
 st.querySelectorAll('.vn-char:not(.vn-actor)').forEach(el=>el.classList.add('vn-actor'));
 actors18().forEach((el,i)=>{
el.dataset.a18='a'+i;
el.style.transformOrigin='center bottom';
el.style.touchAction='none';
el.style.cursor='grab';
 });
 applyTF18();
 applyStageScene();
}
function applyTF18(){
 actors18().forEach(el=>{
const k=el.dataset.a18,t=tf18[k]||{x:0,y:0,s:1};

el.style.transform='translate3d('+t.x+'px,'+t.y+'px,0) scale('+t.s+')';
 });
}
function delta18(dx,dy){
 if(!document.body.classList.contains('ls-mode'))return{x:dx,y:dy};
 return document.body.classList.contains('ls-flip')?{x:-dy,y:dx}:{x:dy,y:-dx};
}
const POKE18={
 warm:['poke18','♡','啊呜',[12]],
 cool:['shake18','…','哼',[22,28,22]],
 spark:['sway18','✦','哔哩',[8,8,8]],
 calm:['poke18','！','嗯？',[10]]
};
const CHAR_POKE18={
 base:'warm',guide:'warm',index:'calm',lastorder:'warm',kuroko:'spark',librarian:'calm',
 accelerator:'cool',kakine:'cool',kanzaki:'cool',mugino:'cool',rightfire:'cool',
 othinus:'cool',styl:'cool',shangli:'cool',sakuyo:'cool',touma:'calm',
 misaka:'spark',shokuhou:'spark',alice:'spark',hamazura:'calm',tsuchimikado:'calm'
};
function poke18(el){
 const k=el.dataset.a18||'a0';
 const id=(questCast(Q(state.active)||currentQuest())||[])[Number(k.slice(1))]||'base';
 const st=CHAR_POKE18[id]||'warm',conf=POKE18[st];
 el.classList.remove('poke18','shake18','sway18');void el.offsetWidth;el.classList.add(conf[0]);
 setTimeout(()=>el.classList.remove(conf[0]),640);
 if(navigator.vibrate)try{navigator.vibrate(conf[3])}catch(e){}
 try{AE._noop('select')}catch(e){}
 const stage=$('#vnStage');if(!stage)return;
 const pop=document.createElement('span');pop.className='vn-poke-pop';
 pop.textContent=conf[1];
 const r=el.getBoundingClientRect(),s=stage.getBoundingClientRect();
 pop.style.left=Math.round(r.left-s.left+r.width*.6)+'px';
 pop.style.top=Math.round(r.top-s.top+r.height*.16)+'px';
 stage.appendChild(pop);setTimeout(()=>pop.remove(),780);
 const say=document.createElement('span');say.className='vn-act-say';say.textContent=conf[2];
 say.style.left=Math.round(r.left-s.left+r.width*.1)+'px';
 say.style.top=Math.round(r.top-s.top+r.height*.42)+'px';
 stage.appendChild(say);setTimeout(()=>say.remove(),900);
}
function dragTag18(txt){
 const st=$('#vnStage');if(!st)return;
 let tag=st.querySelector('.vn-drag-tag');
 if(!tag){tag=document.createElement('span');tag.className='vn-drag-tag';st.appendChild(tag)}
 tag.textContent=txt;tag.classList.add('on');
 clearTimeout(tag._t);tag._t=setTimeout(()=>tag.classList.remove('on'),700);
}
document.addEventListener('pointerdown',e=>{
 const el=e.target.closest&&e.target.closest('#vnStage .vn-actor');if(!el)return;
 pts18.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pts18.size===1){
const t=tf18[el.dataset.a18]||{x:0,y:0,s:1};
drag18={el,sx:e.clientX,sy:e.clientY,x0:t.x,y0:t.y,moved:0};
el.classList.add('dragging18');
 }else if(pts18.size===2){
const p=[...pts18.values()];
pinch18={d:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),s:(tf18[drag18?drag18.el.dataset.a18:'a0']||{s:1}).s};
if(drag18)drag18.moved=99;
 }
},{passive:true});
document.addEventListener('pointermove',e=>{
 if(!drag18&&!pinch18)return;
 if(pts18.has(e.pointerId))pts18.set(e.pointerId,{x:e.clientX,y:e.clientY});
 if(pinch18&&pts18.size>=2){
const p=[...pts18.values()],d=Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),k=drag18?drag18.el.dataset.a18:'a0';
const t=tf18[k]||{x:0,y:0,s:1};t.s=Math.max(.6,Math.min(2.4,pinch18.s*(d/Math.max(1,pinch18.d))));
tf18[k]=t;applyTF18();return;
 }
 if(!drag18)return;
 const dx=e.clientX-drag18.sx,dy=e.clientY-drag18.sy;
 drag18.moved=Math.max(drag18.moved,Math.hypot(dx,dy));
 if(drag18.moved>8)dragTag18('🐾 抓起来啦');
 const d=delta18(dx,dy),k=drag18.el.dataset.a18,t=tf18[k]||{x:0,y:0,s:1};
 t.x=drag18.x0+d.x;t.y=drag18.y0+d.y;tf18[k]=t;applyTF18();
},{passive:true});
function end18(e){
 pts18.delete(e.pointerId);
 if(pts18.size<2)pinch18=null;
 if(drag18){
const dx=(e.clientX||drag18.sx)-drag18.sx,dy=(e.clientY||drag18.sy)-drag18.sy;
const el=drag18.el,k=el.dataset.a18;
el.classList.remove('dragging18');
if(Math.hypot(dx,dy)>=8){
const d=delta18(dx,dy),t=tf18[k]||{x:0,y:0,s:1};
t.x=drag18.x0+d.x;t.y=drag18.y0+d.y;tf18[k]=t;applyTF18();
el.classList.add('land18');setTimeout(()=>el.classList.remove('land18'),420);
dragTag18('轻轻放下～');
}else if(!pinch18)poke18(el);
drag18=null;
 }
}
document.addEventListener('pointerup',end18,{passive:true});
document.addEventListener('pointercancel',end18,{passive:true});
document.addEventListener('click',e=>{
 if(e.target.closest&&e.target.closest('#vnStage .vn-actor'))e.stopPropagation();
},true);
document.addEventListener('dblclick',e=>{
 const el=e.target.closest&&e.target.closest('#vnStage .vn-actor');if(!el)return;
 delete tf18[el.dataset.a18];applyTF18();toast('这只猫的位置已复位');
},{passive:true});
document.addEventListener('wheel',e=>{
 const el=e.target.closest&&e.target.closest('#vnStage .vn-actor');if(!el)return;
 e.preventDefault();
 const k=el.dataset.a18,t=tf18[k]||{x:0,y:0,s:1};
 t.s=Math.max(.6,Math.min(2.4,t.s*(1-e.deltaY*.0012)));tf18[k]=t;applyTF18();
},{passive:false});
