const ENTRY_ART_RULES=[
 [/\b(index|grimoire|librarian)\b|禁书目录|十万三千本/,['guide','index'],'library'],
 [/\b(kamijou|touma)\b|上条|幻想杀手/,['touma'],'balcony'],
 [/\b(misaka|mikoto|railgun)\b|御坂美琴|超电磁炮/,['misaka'],'tokiwadai'],
 [/\b(accelerator)\b|一方通行/,['accelerator'],'dark'],
 [/\b(lastorder)\b|最后之作|妹妹|克隆|御坂网络/,['lastorder'],'river'],
 [/\b(shokuhou)\b|食蜂|心理掌握/,['shokuhou'],'tokiwadai'],
 [/\b(kuroko)\b|白井黑子|风纪委员/,['kuroko'],'tokiwadai'],
 [/\b(kanzaki|styl|church|clear)\b|神裂|史提尔|英国清教|必要之恶|十字架/,['kanzaki','styl'],'library'],
 [/\b(othinus|happy|world)\b|欧提努斯|幸福世界|捣蛋鬼/,['othinus'],'happy'],
 [/\b(rightfire|inferno|war)\b|右方之火|第三次世界大战|白翼/,['rightfire'],'inferno'],
 [/\b(shangli|alice|sakuyo)\b|上里|爱丽丝|去鸣/,['shangli','alice'],'denmark'],
 [/\b(hamazura|tsuchimikado|skill)\b|滨面|土御门|暗部|Skill Out/,['hamazura','tsuchimikado'],'dark'],
 [/\b(kakine|mugino)\b|垣根|麦野|未元物质|原子崩坏/,['kakine','mugino'],'dark'],
 [/学园都市|第七学区|常盘台|大霸星祭|Level|能力|科学侧/,null,'city'],
 [/魔法|魔道书|符文|灵式|圣人|罗马正教|魔法侧/,null,'library'],
 [/丹麦|海域|要塞|新约/,null,'denmark']
];
function entryArt(id,name,cat){
 const key=(id+' '+name+' '+cat).toLowerCase();
 let chars=[],scene=null;
 for(const [re,cs,sc] of ENTRY_ART_RULES){
if(re.test(key)){if(cs)chars=chars.concat(cs);if(!scene)scene=sc;}
 }
 if(!chars.length)chars=cat==='人物'?['guide','touma']:['base','touma'];
 if(!scene)scene='balcony';
 const uq=[...new Set(chars)];
 while(uq.length<2)uq.push(uq[0]==='touma'?'guide':'touma');
 return{chars:uq.slice(0,2),scene};
}
function artSrc(id,scene){
 if(id==='city')return ART.concept.city;
 if(id==='library')return ART.concept.library;
 if(ART.chars[id])return ART.chars[id];
 return ART.scenes[scene+'_h']||ART.scenes.balcony_h;
}
function entryArtHtml(e){
 const a=entryArt(e.id||'',e.name||'',e.cat||'');
 const items=[{src:artSrc(a.scene,a.scene),name:'场景 · '+(ASSET_SCENES.find(x=>x[0]===a.scene)||['','场景板'])[1],tag:'场景板'}]
.concat(a.chars.map(c=>({src:artSrc(c,a.scene),name:(ASSET_CHARS.find(x=>x[0]===c)||['',c])[1],tag:'人物立绘'})));
 return '<div class="entry-art"><b>🖼 相关素材</b><div class="entry-art-grid">'
+items.map((it,i)=>'<button type="button" class="entry-art-th" data-i="'+i+'" title="'+esc(it.name)+'">'
+'<img src="'+it.src+'" alt="'+esc(it.name)+'" loading="lazy"><span>'+esc(it.tag)+'</span></button>').join('')
+'</div><small>点缩略图可放大查看；人物均为哈士喵猫身换装，场景为原创背景美术。</small></div>';
}
function bindEntryArt(){
 const box=$('#entryDetail');if(!box||box.dataset.artBound)return;
 box.dataset.artBound='1';
 new MutationObserver(()=>{
if(box.querySelector('.entry-art'))return;
const h3=box.querySelector('h3');if(!h3||h3.textContent.indexOf('先选择')>=0)return;
const name=h3.textContent.trim();
const e=(DATA.entries||[]).find(x=>x.name===name)||{id:'',name,cat:''};
box.insertAdjacentHTML('beforeend',entryArtHtml(e));
box.querySelectorAll('.entry-art-th').forEach(b=>b.onclick=()=>{
const img=b.querySelector('img');lightbox18(img.src,b.getAttribute('title')||'素材');
});
 }).observe(box,{childList:true,subtree:true});
}
function lightbox18(src,title){
 let lb=$('#lightbox18');
 if(lb){lb.remove();return}
 lb=document.createElement('div');lb.id='lightbox18';lb.className='lightbox18';
 lb.innerHTML='<img src="'+src+'" alt="'+esc(title)+'"><div class="lb18-cap"><b>'+esc(title)+'</b>'
+'<button type="button" id="lb18Close">✕ 关闭</button></div>';
 document.body.appendChild(lb);
 lb.onclick=e=>{if(e.target===lb)lb.remove()};
 lb.querySelector('#lb18Close').onclick=()=>lb.remove();
}
