function applyTF18(){
 var st=v19Stage(),W=st?st.clientWidth:innerWidth,H=st?st.clientHeight:innerHeight;
 actors18().forEach(el=>{
var k=el.dataset.a18||('a'+actors18().indexOf(el)),t=tf18[k]||{x:0,y:0,s:1};
t.x=Math.max(-.55,Math.min(1.15,t.x));
t.y=Math.max(-.9,Math.min(1.25,t.y));
t.s=Math.max(.6,Math.min(2.4,t.s||1));
tf18[k]=t;
el.dataset.a18=k;
el.style.transformOrigin='center bottom';
el.style.transform='translate3d('+(t.x*W).toFixed(1)+'px,'+(t.y*H).toFixed(1)+'px,0) scale('+t.s+')';
el.style.zIndex='14';el.style.pointerEvents='auto';
 });
}
function delta18(dx,dy){
 var st=v19Stage(),W=st?st.clientWidth:innerWidth,H=st?st.clientHeight:innerHeight;
 if(!document.body.classList.contains('ls-mode'))return{x:dx/W,y:dy/H};
 return document.body.classList.contains('ls-flip')?{x:-dy/W,y:dx/H}:{x:dy/W,y:-dx/H};
}

