window.HuskyVoice.record=function(opts){
opts=opts||{};var maxMs=opts.maxMs||15000,self=this;
if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia||!window.MediaRecorder)
return Promise.resolve({error:'当前环境不支持录音，请用「📁 导入文件」选本地音频'});
return new Promise(function(resolve){
navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){
var mime='';
try{
if(MediaRecorder.isTypeSupported('audio/webm;codecs=opus'))mime='audio/webm;codecs=opus';
else if(MediaRecorder.isTypeSupported('audio/mp4'))mime='audio/mp4';
}catch(e){}
var mr;
try{mr=mime?new MediaRecorder(stream,{mimeType:mime}):new MediaRecorder(stream)}
catch(e){try{mr=new MediaRecorder(stream)}catch(e2){resolve({error:'无法创建录音器'});return}}
var chunks=[],done=false,timer=null,tick=null;
function finish(payload){
if(done)return;done=true;clearTimeout(timer);clearInterval(tick);
try{stream.getTracks().forEach(function(t){t.stop()})}catch(e){}
self._rec=null;resolve(payload);
}
mr.ondataavailable=function(e){if(e.data&&e.data.size)chunks.push(e.data)};
mr.onerror=function(){finish({error:'录音中断，请再试一次'})};
mr.onstop=function(){
try{
var blob=new Blob(chunks,{type:mr.mimeType||'audio/webm'});
finish({blob:blob,url:URL.createObjectURL(blob),size:blob.size});
}catch(e){finish({error:'生成音频失败'})}
};
try{mr.start()}catch(e){finish({error:'无法开始录音'});return}
self._rec={stop:function(){if(mr.state!=='inactive')try{mr.stop()}catch(e){}},state:function(){return mr.state}};
timer=setTimeout(function(){if(mr.state!=='inactive')try{mr.stop()}catch(e){}},maxMs);
if(opts.onTick){var t0=Date.now();tick=setInterval(function(){if(!done)opts.onTick((Date.now()-t0)/1000)},100)}
}).catch(function(e){
resolve({error:'麦克风不可用：'+((e&&e.message)||'权限被拒绝')+'，可改用「📁 导入文件」'});
});
});
};
window.HuskyVoice.stopRecord=function(){if(this._rec)try{this._rec.stop()}catch(e){}};

