var v75AutoOn=false,v75AutoTimer=null;
function v75AutoStop(){v75AutoOn=false;if(v75AutoTimer){clearTimeout(v75AutoTimer);v75AutoTimer=null}v75AutoBtn()}
function v75AutoTick(){
 if(!v75AutoOn)return;
 if(vnStep>=vnLines.length){v75AutoStop();return}
 var L=vnLines[vnStep]||{text:''};
 var ms=Math.min(3200,620+String(L.text).length*64);
 v75AutoTimer=setTimeout(function(){
  if(!v75AutoOn)return;
  try{if(typeof vnTimer!=='undefined'&&vnTimer&&typeof vnComplete==='function')vnComplete()}catch(e){}
  try{vnNext()}catch(e){v75AutoStop();return}
  v75AutoTick();
 },ms);
}
